import {mountPreferences} from '../app/preferences.js';
import {Hero} from './Hero.js';
import {latestProject} from '../project/project.js';
export class Home{
 constructor(root,onLab,onResume,heroSettings){this.root=root;this.root.innerHTML=`<div class="home-screen"><div class="home-meta"><div>SEKRET / DESIGN ON YOUR OWN TERMS</div><div>CREATIVE SOFTWARE / DESIGN LABORATORY <span class="online-dot">●</span></div></div>
 <div class="home-hero"><div class="hero-topline"><a class="sub-tag" href="https://t.me/sekretiktg" target="_blank" rel="noopener noreferrer">[ TG / @sekretiktg ]</a><a class="sub-tag" href="https://t.me/sekretikDesign" target="_blank" rel="noopener noreferrer">t.me/sekretikDesign ↗</a></div><canvas id="hero-canvas" aria-label="Interactive SEKRET eye symbol"></canvas><img class="hero-svg-fallback" src="/assets/brand/sekret_main_logo.svg" alt="SEKRET symbol" /><div class="hero-copy"><div class="hero-name">SEKRET<span>®</span></div><div class="hero-bottom"><p>Turn photographs into graphic matter. Turn sound into moving form. Three laboratories. One creative instinct.</p><h1><em>FOR THE UNEXPECTED.</em><br>VISUAL SYSTEMS</h1></div></div><div class="hero-corner">VOL. 05 — FORM FOLLOWS FREQUENCY</div></div>
 <nav class="hero-lab-nav" aria-label="Laboratories"><button data-go="image">01 / PHOTO ↗</button><button data-go="audio">02 / AUDIO ↗</button><button data-go="generative">03 / GENERATIVE ↗</button></nav><div class="home-choice-label"><span>01 / CREATIVE LABORATORIES</span><span>[ OPEN A LABORATORY BELOW ]</span></div><div class="home-choices">
 <button class="home-choice" data-go="image"><span class="home-choice-top">[ 01 ] / PHOTO EFFECT SYSTEMS <b>↗</b></span><span class="choice-visual image-visual"><img class="lab-preview" data-preview="photo" alt="" hidden><span class="image-graphic">S</span><span class="image-graphic-shadow">S</span><span class="choice-scanline"></span></span><span class="choice-details"><strong>PHOTO <i>LABORATORY</i></strong><span>PIXEL / PRINT / GLITCH / COLOR / TEXTURE</span></span></button>
 <button class="home-choice" data-go="audio"><span class="home-choice-top">[ 02 ] / REALTIME GENERATIVE MOTION <b>↗</b></span><span class="choice-visual audio-visual"><img class="lab-preview" data-preview="audio" alt="" hidden><canvas id="home-preview-audio" width="640" height="280" aria-hidden="true"></canvas><span class="choice-visual-label">FREQUENCY / SPACE</span></span><span class="choice-details"><strong>AUDIO <i>LABORATORY</i></strong><span>SOUND / PARTICLES / TYPE / FEEDBACK</span></span></button>
 <button class="home-choice" data-go="generative"><span class="home-choice-top">[ 03 ] / CREATE FROM NOTHING <b>↗</b></span><span class="choice-visual generative-visual"><canvas id="home-preview-generative" width="640" height="360" aria-hidden="true"></canvas><span class="choice-visual-label">FORM / FIELD / FORCE</span></span><span class="choice-details"><strong>GENERATIVE <i>LABORATORY</i></strong><span>SCULPTURE / FIELDS / TYPE / INTERACTION</span></span></button></div>
 <div class="home-choice-label"><span>02 / TOOLS & EXPERIMENTS</span><span>[ SPECIALIZED CREATIVE TOOLS ]</span></div><div class="home-tools"><button data-go="webfx"><span>04 / WEB FX ↗</span><strong>MOVE THE WEB.</strong><small>INTERACTIVE WEB EFFECTS / OPEN SOURCE</small><i class="tool-orb"></i></button><button data-go="forge"><span>05 / ASSET FORGE ↗</span><strong>MAKE YOUR MARK.</strong><small>PROCEDURAL DESIGN ASSETS</small><i class="tool-mark">✳</i></button></div><div class="home-workflows"><span>START WITH AN IDEA</span><button id="home-guide">START HERE / TAKE THE TOUR ↗</button><button data-go="image">CREATE A POSTER ↗</button><button data-go="audio">MAKE AN AUDIO VISUAL ↗</button><button data-go="generative">CREATE A COMPOSITION ↗</button><button data-go="webfx">CREATE A WEB EFFECT ↗</button><button data-go="forge" data-workflow="pattern">GENERATE A PATTERN ↗</button></div>
 <div class="home-footer"><span>SEKRET TOOLS LAB © 2026</span><div><a href="https://t.me/sekretiktg" target="_blank" rel="noopener noreferrer">TELEGRAM: @sekretiktg ↗</a><span>DESIGN CHANNEL: SEKRET DESIGN</span><span>LOCAL PROCESSING</span><button id="resume-project" class="resume-link" hidden>↗ RESUME LAST PROJECT</button></div></div></div>`;
 this.root.querySelector('#home-guide').onclick=()=>document.dispatchEvent(new Event('sekret-guide'));mountPreferences(this.root.querySelector('.home-meta'));this.root.querySelectorAll('[data-preview]').forEach(img=>{img.onload=()=>{img.hidden=false;img.parentElement.classList.add('has-preview')};img.onerror=()=>{img.hidden=true;img.parentElement.classList.remove('has-preview')};img.src='/assets/brand/'+img.dataset.preview+'_visual_lab_preview.png';});
 this.hero=new Hero(root.querySelector('#hero-canvas'),heroSettings);this.onPointer=e=>{const r=root.querySelector('.home-hero').getBoundingClientRect();root.querySelector('.home-hero').style.setProperty('--eye-x',((e.clientX-r.left)/r.width-.5).toFixed(3));root.querySelector('.home-hero').style.setProperty('--eye-y',((e.clientY-r.top)/r.height-.5).toFixed(3));};root.querySelector('.home-hero').addEventListener('pointermove',this.onPointer);this.drawAudioPreview();this.drawGenerativePreview();this.root.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{onLab(x.dataset.go);if(x.dataset.workflow==='pattern')document.dispatchEvent(new CustomEvent('sekret-workflow',{detail:'pattern'}));});const prior=latestProject();if(prior){const button=root.querySelector('#resume-project');button.hidden=false;button.onclick=()=>onResume(prior)} }
 drawAudioPreview(){const c=this.root.querySelector('#home-preview-audio'),g=c.getContext('2d');g.fillStyle='#08080a';g.fillRect(0,0,c.width,c.height);let lines=26;for(let l=0;l<lines;l++){const k=l/lines;g.beginPath();for(let x=0;x<c.width;x+=2){const y=145+(Math.sin(x*.009+l*.42)*Math.cos(x*.023-l*.3)*32+Math.sin(x*.019+l*.21)*26)*(1-k*.4)+(k-.5)*90;if(x===0)g.moveTo(x,y);else g.lineTo(x,y)}g.strokeStyle=`rgba(245,236,235,${.05+(1-k)*.16})`;g.lineWidth=.8;g.stroke()}
 const grad=g.createLinearGradient(0,0,c.width,c.height);grad.addColorStop(0,'#bbb');grad.addColorStop(.5,'#9e4b64');grad.addColorStop(1,'#fff');g.strokeStyle=grad;g.lineWidth=1.3;for(let y=0;y<8;y++){g.beginPath();for(let x=0;x<c.width;x+=2){const yy=140+y*1.5+Math.sin(x*.014+y*.16)*Math.cos(x*.045-y*.1)*75;if(x===0)g.moveTo(x,yy);else g.lineTo(x,yy)}g.globalAlpha=.17;g.stroke()}g.globalAlpha=1;
 }
 drawGenerativePreview(){const c=this.root.querySelector('#home-preview-generative'),g=c.getContext('2d');g.fillStyle='#08080a';g.fillRect(0,0,640,360);g.globalCompositeOperation='lighter';
 for(let i=0;i<72;i++){const a=i/72*Math.PI*2;g.beginPath();for(let j=0;j<=180;j++){const b=j/180*Math.PI*2,rad=108+28*Math.cos(b*3+a*2);const x=320+Math.cos(a)*rad+Math.sin(b)*64,y=180+Math.sin(a)*rad*.6+Math.cos(b*2+a)*25;if(j===0)g.moveTo(x,y);else g.lineTo(x,y);}g.strokeStyle=i%4===0?'rgba(236,215,222,.18)':'rgba(128,47,73,.16)';g.lineWidth=.6;g.stroke();}g.globalCompositeOperation='source-over';}
 dispose(){this.root.querySelector('.home-hero')?.removeEventListener('pointermove',this.onPointer);this.hero?.dispose();this.root.innerHTML='';}
}
